#include <stdio.h>

typedef struct { int year, month, day; } Date;

int day_of_year(int year, int month, int day) {
    int days[] = {31,28,31,30,31,30,31,31,30,31,30,31};
    if (year % 400 == 0 || (year % 4 == 0 && year % 100 != 0)) days[1] = 29;
    int answer = day;
    for (int i = 0; i < month - 1; i++) answer += days[i];
    return answer;
}

int ordinal(Date date) { return day_of_year(date.year, date.month, date.day); }

int main(void) {
    Date date;
    scanf("%d%d%d", &date.year, &date.month, &date.day);
    printf("%d\n", ordinal(date));
    return 0;
}
